//! SkyFrame Norm and the SkyTol and Equinox setters, checked against the C
//! library (`sky_norm_oracle/cases.rs`, generated by
//! `tools/oracle_fixtures/sky_norm_probe.c`).

#[path = "sky_norm_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{Frame, SkyFrame, SkySystem};

#[test]
fn norm_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(permuted, neglon, input, want) in cases::NORM_CASES {
        let mut f = SkyFrame::unset_system();
        if permuted {
            f.perm_axes(&[2, 1]).unwrap();
        }
        if neglon {
            f.set_neg_lon(true);
        }
        let mut v = input;
        f.norm(&mut v).unwrap();
        if v != want {
            failures.push(format!(
                "permuted {permuted} neglon {neglon} {input:?}: got {v:?}, C gives {want:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn setters_match_the_c_library() {
    let mut helio = SkyFrame::unset_system();
    helio.set_system(SkySystem::Helioecliptic);
    helio.set_equinox_year(1975.0);
    assert_eq!(helio.test_equinox(), cases::HELIO_EQUINOX_SET);

    let mut f = SkyFrame::unset_system();
    f.set_sky_tol(-0.5);
    assert_eq!(f.sky_tol(), cases::SKYTOL);
}
